// Points a Sphinx scores for the variety of monster types beside it,
// richest variety first.
const SCORE_BY_TYPE_COUNT: ReadonlyArray<{
  atLeastTypes: number;
  score: number;
}> = [
  { atLeastTypes: 6, score: 5 },
  { atLeastTypes: 5, score: 3 },
];

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;

  const typeCount = countDistinctMonsterTypes(army);
  const bonus = SCORE_BY_TYPE_COUNT.find(
    ({ atLeastTypes }) => typeCount >= atLeastTypes,
  );

  return bonus?.score ?? BASE_SPHINX_SCORE;
};

